     1→use crate::proto;
     2→use spec_core::{EdgeKind, FileStore, NodeKind, SpecGraph};
     3→use std::path::PathBuf;
     4→use std::sync::Mutex;
     5→use tonic::{Request, Response, Status};
     6→
     7→pub struct SpecOracleService {
     8→    graph: Mutex<SpecGraph>,
     9→    store: FileStore,
    10→}
    11→
    12→impl SpecOracleService {
    13→    pub fn new(store_path: PathBuf) -> Result<Self, Box<dyn std::error::Error>> {
    14→        let store = FileStore::new(&store_path);
    15→        let graph = store.load()?;
    16→        Ok(Self {
    17→            graph: Mutex::new(graph),
    18→            store,
    19→        })
    20→    }
    21→
    22→    fn save(&self, graph: &SpecGraph) -> Result<(), Status> {
    23→        self.store
    24→            .save(graph)
    25→            .map_err(|e| Status::internal(format!("Failed to persist: {e}")))
    26→    }
    27→}
    28→
    29→fn to_proto_node(n: &spec_core::SpecNodeData) -> proto::SpecNode {
    30→    proto::SpecNode {
    31→        id: n.id.clone(),
    32→        content: n.content.clone(),
    33→        kind: to_proto_node_kind(n.kind).into(),
    34→        metadata: n.metadata.clone(),
    35→        created_at: n.created_at,
    36→        modified_at: n.modified_at,
    37→        formality_layer: n.formality_layer as u32,
    38→    }
    39→}
    40→
    41→fn to_proto_node_kind(k: NodeKind) -> proto::SpecNodeKind {
    42→    match k {
    43→        NodeKind::Assertion => proto::SpecNodeKind::Assertion,
    44→        NodeKind::Constraint => proto::SpecNodeKind::Constraint,
    45→        NodeKind::Scenario => proto::SpecNodeKind::Scenario,
    46→        NodeKind::Definition => proto::SpecNodeKind::Definition,
    47→        NodeKind::Domain => proto::SpecNodeKind::Domain,
    48→    }
    49→}
    50→
    51→fn from_proto_node_kind(k: i32) -> NodeKind {
    52→    match proto::SpecNodeKind::try_from(k) {
    53→        Ok(proto::SpecNodeKind::Assertion) => NodeKind::Assertion,
    54→        Ok(proto::SpecNodeKind::Constraint) => NodeKind::Constraint,
    55→        Ok(proto::SpecNodeKind::Scenario) => NodeKind::Scenario,
    56→        Ok(proto::SpecNodeKind::Definition) => NodeKind::Definition,
    57→        Ok(proto::SpecNodeKind::Domain) => NodeKind::Domain,
    58→        _ => NodeKind::Assertion,
    59→    }
    60→}
    61→
    62→fn to_proto_edge(e: &spec_core::SpecEdgeData, src: &str, tgt: &str) -> proto::SpecEdge {
    63→    proto::SpecEdge {
    64→        id: e.id.clone(),
    65→        source_id: src.to_string(),
    66→        target_id: tgt.to_string(),
    67→        kind: to_proto_edge_kind(e.kind).into(),
    68→        metadata: e.metadata.clone(),
    69→        created_at: e.created_at,
    70→    }
    71→}
    72→
    73→fn to_proto_edge_kind(k: EdgeKind) -> proto::SpecEdgeKind {
    74→    match k {
    75→        EdgeKind::Refines => proto::SpecEdgeKind::Refines,
    76→        EdgeKind::DependsOn => proto::SpecEdgeKind::DependsOn,
    77→        EdgeKind::Contradicts => proto::SpecEdgeKind::Contradicts,
    78→        EdgeKind::DerivesFrom => proto::SpecEdgeKind::DerivesFrom,
    79→        EdgeKind::Synonym => proto::SpecEdgeKind::Synonym,
    80→        EdgeKind::Composes => proto::SpecEdgeKind::Composes,
    81→        EdgeKind::Formalizes => proto::SpecEdgeKind::Formalizes,
    82→        EdgeKind::Transform => proto::SpecEdgeKind::Transform,
    83→    }
    84→}
    85→
    86→fn from_proto_edge_kind(k: i32) -> EdgeKind {
    87→    match proto::SpecEdgeKind::try_from(k) {
    88→        Ok(proto::SpecEdgeKind::Refines) => EdgeKind::Refines,
    89→        Ok(proto::SpecEdgeKind::DependsOn) => EdgeKind::DependsOn,
    90→        Ok(proto::SpecEdgeKind::Contradicts) => EdgeKind::Contradicts,
    91→        Ok(proto::SpecEdgeKind::DerivesFrom) => EdgeKind::DerivesFrom,
    92→        Ok(proto::SpecEdgeKind::Synonym) => EdgeKind::Synonym,
    93→        Ok(proto::SpecEdgeKind::Composes) => EdgeKind::Composes,
    94→        Ok(proto::SpecEdgeKind::Formalizes) => EdgeKind::Formalizes,
    95→        Ok(proto::SpecEdgeKind::Transform) => EdgeKind::Transform,
    96→        _ => EdgeKind::DependsOn,
    97→    }
    98→}
    99→
   100→#[tonic::async_trait]
   101→impl proto::spec_oracle_server::SpecOracle for SpecOracleService {
   102→    async fn add_node(
   103→        &self,
   104→        request: Request<proto::AddNodeRequest>,
   105→    ) -> Result<Response<proto::AddNodeResponse>, Status> {
   106→        let req = request.into_inner();
   107→        let mut graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   108→
   109→        let formality_layer = req.metadata.get("formality_layer")
   110→            .and_then(|s| s.parse::<u8>().ok())
   111→            .unwrap_or(0);
   112→
   113→        let node = graph.add_node_with_layer(
   114→            req.content,
   115→            from_proto_node_kind(req.kind),
   116→            formality_layer,
   117→            req.metadata,
   118→        );
   119→        let resp = proto::AddNodeResponse {
   120→            node: Some(to_proto_node(&node)),
   121→        };
   122→        self.save(&graph)?;
   123→        Ok(Response::new(resp))
   124→    }
   125→
   126→    async fn get_node(
   127→        &self,
   128→        request: Request<proto::GetNodeRequest>,
   129→    ) -> Result<Response<proto::GetNodeResponse>, Status> {
   130→        let req = request.into_inner();
   131→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   132→        let node = graph
   133→            .get_node(&req.id)
   134→            .ok_or_else(|| Status::not_found(format!("Node {} not found", req.id)))?;
   135→        Ok(Response::new(proto::GetNodeResponse {
   136→            node: Some(to_proto_node(node)),
   137→        }))
   138→    }
   139→
   140→    async fn list_nodes(
   141→        &self,
   142→        request: Request<proto::ListNodesRequest>,
   143→    ) -> Result<Response<proto::ListNodesResponse>, Status> {
   144→        let req = request.into_inner();
   145→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   146→        let filter = if req.kind_filter == 0 {
   147→            None
   148→        } else {
   149→            Some(from_proto_node_kind(req.kind_filter))
   150→        };
   151→        let nodes: Vec<proto::SpecNode> = graph.list_nodes(filter).into_iter().map(to_proto_node).collect();
   152→        Ok(Response::new(proto::ListNodesResponse { nodes }))
   153→    }
   154→
   155→    async fn remove_node(
   156→        &self,
   157→        request: Request<proto::RemoveNodeRequest>,
   158→    ) -> Result<Response<proto::RemoveNodeResponse>, Status> {
   159→        let req = request.into_inner();
   160→        let mut graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   161→        graph
   162→            .remove_node(&req.id)
   163→            .ok_or_else(|| Status::not_found(format!("Node {} not found", req.id)))?;
   164→        self.save(&graph)?;
   165→        Ok(Response::new(proto::RemoveNodeResponse {}))
   166→    }
   167→
   168→    async fn add_edge(
   169→        &self,
   170→        request: Request<proto::AddEdgeRequest>,
   171→    ) -> Result<Response<proto::AddEdgeResponse>, Status> {
   172→        let req = request.into_inner();
   173→        let mut graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   174→        let edge = graph
   175→            .add_edge(
   176→                &req.source_id,
   177→                &req.target_id,
   178→                from_proto_edge_kind(req.kind),
   179→                req.metadata,
   180→            )
   181→            .map_err(|e| Status::not_found(e.to_string()))?;
   182→        let resp = proto::AddEdgeResponse {
   183→            edge: Some(to_proto_edge(edge, &req.source_id, &req.target_id)),
   184→        };
   185→        self.save(&graph)?;
   186→        Ok(Response::new(resp))
   187→    }
   188→
   189→    async fn list_edges(
   190→        &self,
   191→        request: Request<proto::ListEdgesRequest>,
   192→    ) -> Result<Response<proto::ListEdgesResponse>, Status> {
   193→        let req = request.into_inner();
   194→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   195→        let node_id = if req.node_id.is_empty() {
   196→            None
   197→        } else {
   198→            Some(req.node_id.as_str())
   199→        };
   200→        let edges: Vec<proto::SpecEdge> = graph
   201→            .list_edges(node_id)
   202→            .into_iter()
   203→            .map(|(e, src, tgt)| to_proto_edge(e, src, tgt))
   204→            .collect();
   205→        Ok(Response::new(proto::ListEdgesResponse { edges }))
   206→    }
   207→
   208→    async fn remove_edge(
   209→        &self,
   210→        request: Request<proto::RemoveEdgeRequest>,
   211→    ) -> Result<Response<proto::RemoveEdgeResponse>, Status> {
   212→        let req = request.into_inner();
   213→        let mut graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   214→        graph
   215→            .remove_edge(&req.id)
   216→            .ok_or_else(|| Status::not_found(format!("Edge {} not found", req.id)))?;
   217→        self.save(&graph)?;
   218→        Ok(Response::new(proto::RemoveEdgeResponse {}))
   219→    }
   220→
   221→    async fn query(
   222→        &self,
   223→        request: Request<proto::QueryRequest>,
   224→    ) -> Result<Response<proto::QueryResponse>, Status> {
   225→        let req = request.into_inner();
   226→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   227→        let matching: Vec<proto::SpecNode> = graph
   228→            .search(&req.natural_language_query)
   229→            .into_iter()
   230→            .map(to_proto_node)
   231→            .collect();
   232→        let explanation = if matching.is_empty() {
   233→            "No matching specifications found.".to_string()
   234→        } else {
   235→            format!("Found {} matching specification(s).", matching.len())
   236→        };
   237→        Ok(Response::new(proto::QueryResponse {
   238→            matching_nodes: matching,
   239→            explanation,
   240→        }))
   241→    }
   242→
   243→    async fn detect_contradictions(
   244→        &self,
   245→        _request: Request<proto::DetectContradictionsRequest>,
   246→    ) -> Result<Response<proto::DetectContradictionsResponse>, Status> {
   247→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   248→        let contradictions: Vec<proto::Contradiction> = graph
   249→            .detect_contradictions()
   250→            .into_iter()
   251→            .map(|c| proto::Contradiction {
   252→                node_a: Some(to_proto_node(&c.node_a)),
   253→                node_b: Some(to_proto_node(&c.node_b)),
   254→                explanation: c.explanation,
   255→            })
   256→            .collect();
   257→        Ok(Response::new(proto::DetectContradictionsResponse {
   258→            contradictions,
   259→        }))
   260→    }
   261→
   262→    async fn detect_omissions(
   263→        &self,
   264→        _request: Request<proto::DetectOmissionsRequest>,
   265→    ) -> Result<Response<proto::DetectOmissionsResponse>, Status> {
   266→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   267→        let omissions: Vec<proto::Omission> = graph
   268→            .detect_omissions()
   269→            .into_iter()
   270→            .map(|o| proto::Omission {
   271→                description: o.description,
   272→                related_nodes: o.related_nodes.iter().map(to_proto_node).collect(),
   273→            })
   274→            .collect();
   275→        Ok(Response::new(proto::DetectOmissionsResponse { omissions }))
   276→    }
   277→
   278→    async fn resolve_terminology(
   279→        &self,
   280→        request: Request<proto::ResolveTerminologyRequest>,
   281→    ) -> Result<Response<proto::ResolveTerminologyResponse>, Status> {
   282→        let req = request.into_inner();
   283→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   284→        let (defs, synonyms) = graph.resolve_term(&req.term);
   285→        Ok(Response::new(proto::ResolveTerminologyResponse {
   286→            definitions: defs.into_iter().map(to_proto_node).collect(),
   287→            synonyms,
   288→        }))
   289→    }
   290→
   291→    async fn detect_layer_inconsistencies(
   292→        &self,
   293→        _request: Request<proto::DetectLayerInconsistenciesRequest>,
   294→    ) -> Result<Response<proto::DetectLayerInconsistenciesResponse>, Status> {
   295→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   296→        let inconsistencies: Vec<proto::LayerInconsistency> = graph
   297→            .detect_layer_inconsistencies()
   298→            .into_iter()
   299→            .map(|i| proto::LayerInconsistency {
   300→                source: Some(to_proto_node(&i.source)),
   301→                target: Some(to_proto_node(&i.target)),
   302→                explanation: i.explanation,
   303→            })
   304→            .collect();
   305→        Ok(Response::new(proto::DetectLayerInconsistenciesResponse {
   306→            inconsistencies,
   307→        }))
   308→    }
   309→
   310→    async fn filter_by_layer(
   311→        &self,
   312→        request: Request<proto::FilterByLayerRequest>,
   313→    ) -> Result<Response<proto::FilterByLayerResponse>, Status> {
   314→        let req = request.into_inner();
   315→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   316→        let nodes: Vec<proto::SpecNode> = graph
   317→            .filter_by_layer(req.min_layer as u8, req.max_layer as u8)
   318→            .into_iter()
   319→            .map(to_proto_node)
   320→            .collect();
   321→        Ok(Response::new(proto::FilterByLayerResponse { nodes }))
   322→    }
   323→
   324→    async fn find_formalizations(
   325→        &self,
   326→        request: Request<proto::FindFormalizationsRequest>,
   327→    ) -> Result<Response<proto::FindFormalizationsResponse>, Status> {
   328→        let req = request.into_inner();
   329→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   330→        let formalizations: Vec<proto::SpecNode> = graph
   331→            .find_formalizations(&req.node_id)
   332→            .into_iter()
   333→            .map(to_proto_node)
   334→            .collect();
   335→        let natural_sources: Vec<proto::SpecNode> = graph
   336→            .find_natural_source(&req.node_id)
   337→            .into_iter()
   338→            .map(to_proto_node)
   339→            .collect();
   340→        Ok(Response::new(proto::FindFormalizationsResponse {
   341→            formalizations,
   342→            natural_sources,
   343→        }))
   344→    }
   345→
   346→    async fn find_related_terms(
   347→        &self,
   348→        request: Request<proto::FindRelatedTermsRequest>,
   349→    ) -> Result<Response<proto::FindRelatedTermsResponse>, Status> {
   350→        let req = request.into_inner();
   351→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   352→        let mut related = graph.find_related_terms(&req.term);
   353→
   354→        if req.max_results > 0 && related.len() > req.max_results as usize {
   355→            related.truncate(req.max_results as usize);
   356→        }
   357→
   358→        let nodes: Vec<proto::ScoredNode> = related
   359→            .into_iter()
   360→            .map(|(node, score)| proto::ScoredNode {
   361→                node: Some(to_proto_node(node)),
   362→                score,
   363→            })
   364→            .collect();
   365→
   366→        Ok(Response::new(proto::FindRelatedTermsResponse { nodes }))
   367→    }
   368→
   369→    async fn detect_potential_synonyms(
   370→        &self,
   371→        request: Request<proto::DetectPotentialSynonymsRequest>,
   372→    ) -> Result<Response<proto::DetectPotentialSynonymsResponse>, Status> {
   373→        let req = request.into_inner();
   374→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   375→        let min_sim = if req.min_similarity > 0.0 {
   376→            req.min_similarity
   377→        } else {
   378→            0.3
   379→        };
   380→
   381→        let candidates: Vec<proto::SynonymCandidate> = graph
   382→            .detect_potential_synonyms()
   383→            .into_iter()
   384→            .filter(|(_, _, sim)| *sim >= min_sim)
   385→            .map(|(node_a, node_b, similarity)| proto::SynonymCandidate {
   386→                node_a: Some(to_proto_node(&node_a)),
   387→                node_b: Some(to_proto_node(&node_b)),
   388→                similarity,
   389→            })
   390→            .collect();
   391→
   392→        Ok(Response::new(proto::DetectPotentialSynonymsResponse {
   393→            candidates,
   394→        }))
   395→    }
   396→
   397→    async fn generate_contract_template(
   398→        &self,
   399→        request: Request<proto::GenerateContractTemplateRequest>,
   400→    ) -> Result<Response<proto::GenerateContractTemplateResponse>, Status> {
   401→        let req = request.into_inner();
   402→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   403→
   404→        let template = graph
   405→            .generate_contract_template(&req.node_id, &req.language)
   406→            .ok_or_else(|| Status::not_found("Node not found or not testable"))?;
   407→
   408→        let node = graph
   409→            .get_node(&req.node_id)
   410→            .ok_or_else(|| Status::not_found("Node not found"))?;
   411→
   412→        let node_kind = match node.kind {
   413→            spec_core::NodeKind::Constraint => "constraint",
   414→            spec_core::NodeKind::Scenario => "scenario",
   415→            _ => "unknown",
   416→        };
   417→
   418→        Ok(Response::new(proto::GenerateContractTemplateResponse {
   419→            template,
   420→            node_kind: node_kind.to_string(),
   421→        }))
   422→    }
   423→
   424→    async fn get_test_coverage(
   425→        &self,
   426→        _request: Request<proto::GetTestCoverageRequest>,
   427→    ) -> Result<Response<proto::GetTestCoverageResponse>, Status> {
   428→        let graph = self.graph.lock().map_err(|e| Status::internal(e.to_string()))?;
   429→        let coverage = graph.get_test_coverage();
   430→
   431→        Ok(Response::new(proto::GetTestCoverageResponse {
   432→            total_testable: coverage.total_testable as u32,
   433→            with_tests: coverage.with_tests as u32,
   434→            coverage_ratio: coverage.coverage_ratio,
   435→            nodes_with_tests: coverage
   436→                .nodes_with_tests
   437→                .iter()
   438→                .map(to_proto_node)
   439→                .collect(),
   440→            nodes_without_tests: coverage
