syntax = "proto3";

package spec_oracle;

service SpecOracle {
  // Node operations
  rpc AddNode(AddNodeRequest) returns (AddNodeResponse);
  rpc GetNode(GetNodeRequest) returns (GetNodeResponse);
  rpc ListNodes(ListNodesRequest) returns (ListNodesResponse);
  rpc RemoveNode(RemoveNodeRequest) returns (RemoveNodeResponse);

  // Edge operations
  rpc AddEdge(AddEdgeRequest) returns (AddEdgeResponse);
  rpc ListEdges(ListEdgesRequest) returns (ListEdgesResponse);
  rpc RemoveEdge(RemoveEdgeRequest) returns (RemoveEdgeResponse);

  // Query and analysis
  rpc Query(QueryRequest) returns (QueryResponse);
  rpc DetectContradictions(DetectContradictionsRequest) returns (DetectContradictionsResponse);
  rpc DetectOmissions(DetectOmissionsRequest) returns (DetectOmissionsResponse);
  rpc DetectLayerInconsistencies(DetectLayerInconsistenciesRequest) returns (DetectLayerInconsistenciesResponse);

  // Terminology resolution
  rpc ResolveTerminology(ResolveTerminologyRequest) returns (ResolveTerminologyResponse);

  // Layer-aware operations
  rpc FilterByLayer(FilterByLayerRequest) returns (FilterByLayerResponse);
  rpc FindFormalizations(FindFormalizationsRequest) returns (FindFormalizationsResponse);

  // Semantic normalization
  rpc FindRelatedTerms(FindRelatedTermsRequest) returns (FindRelatedTermsResponse);
  rpc DetectPotentialSynonyms(DetectPotentialSynonymsRequest) returns (DetectPotentialSynonymsResponse);

  // Executable contracts
  rpc GenerateContractTemplate(GenerateContractTemplateRequest) returns (GenerateContractTemplateResponse);
  rpc GetTestCoverage(GetTestCoverageRequest) returns (GetTestCoverageResponse);

  // Graded compliance
  rpc CalculateCompliance(CalculateComplianceRequest) returns (CalculateComplianceResponse);
  rpc GetComplianceReport(GetComplianceReportRequest) returns (GetComplianceReportResponse);

  // Temporal queries
  rpc QueryAtTimestamp(QueryAtTimestampRequest) returns (QueryAtTimestampResponse);
  rpc DiffTimestamps(DiffTimestampsRequest) returns (DiffTimestampsResponse);
  rpc GetNodeHistory(GetNodeHistoryRequest) returns (GetNodeHistoryResponse);
  rpc GetComplianceTrend(GetComplianceTrendRequest) returns (GetComplianceTrendResponse);

  // Inter-universe consistency (conversation.md U, D, A, f implementation)
  rpc DetectInterUniverseInconsistencies(DetectInterUniverseInconsistenciesRequest) returns (DetectInterUniverseInconsistenciesResponse);
  rpc SetNodeUniverse(SetNodeUniverseRequest) returns (SetNodeUniverseResponse);

  // Automatic relationship inference
  rpc InferAllRelationships(InferAllRelationshipsRequest) returns (InferAllRelationshipsResponse);

  // AI-powered relationship inference (cross-layer semantic matching)
  rpc InferAllRelationshipsWithAi(InferAllRelationshipsWithAiRequest) returns (InferAllRelationshipsResponse);
}

// --- Node types ---

message SpecNode {
  string id = 1;
  string content = 2;
  SpecNodeKind kind = 3;
  map<string, string> metadata = 4;
  int64 created_at = 5;
  int64 modified_at = 6;
  uint32 formality_layer = 7;  // 0=natural, 1=structured, 2=formal, 3=executable
}

enum SpecNodeKind {
  SPEC_NODE_KIND_UNSPECIFIED = 0;
  ASSERTION = 1;       // A concrete claim about behavior
  CONSTRAINT = 2;      // A universal constraint (invariant)
  SCENARIO = 3;        // An existential requirement (a path that must exist)
  DEFINITION = 4;      // A term definition
  DOMAIN = 5;          // A domain boundary declaration
}

// --- Edge types ---

message SpecEdge {
  string id = 1;
  string source_id = 2;
  string target_id = 3;
  SpecEdgeKind kind = 4;
  map<string, string> metadata = 5;
  int64 created_at = 6;
}

enum SpecEdgeKind {
  SPEC_EDGE_KIND_UNSPECIFIED = 0;
  REFINES = 1;         // Target refines source (is more specific)
  DEPENDS_ON = 2;      // Source depends on target
  CONTRADICTS = 3;     // Source contradicts target
  DERIVES_FROM = 4;    // Source is derived from target
  SYNONYM = 5;         // Source and target are synonymous terms
  COMPOSES = 6;        // Source composes with target into a higher-level spec
  FORMALIZES = 7;      // Target is a more formal version of source
  TRANSFORM = 8;       // Function f: maps spec from source universe to target universe

content.thinking:
ユーザーは「layerの数値だけで宇宙が一意に定まるのか？」という質問をしていると思われます。

コードを見ると：
- Universe.id が "U0", "U1", "U2" のように付けられている
- Universe.layer が 0, 1, 2, 3... という数値

しかし、実際には同じ layer に複数の異なる宇宙が存在できるはずです。例えば：
- layer 3 に「Rust実装」と「PHP実装」という2つの異なる宇宙
- layer 1 に「TLA+仕様」と「Alloy仕様」という2つの異なる宇宙

コードを見ると、`add_universe()` では：
```rust
pub fn add_universe(&mut self, layer: u8, name: String, description: String) -> String {
    let universe = Universe::projection(layer, name, description);
    let id = universe.id.clone();
    self.universes.insert(id.clone(), universe);
    id
}
```

そして `Universe::projection()` では：
```rust
pub fn projection(layer: u8, name: String, description: String) -> Self {
    assert!(layer > 0, "U0 is reserved for root universe");
    Self {
        id: format!("U{}", layer),  // <-- ここが問題
        layer,
        name,
        description,
        specifications: HashSet::new(),
        metadata: HashMap::new(),
    }
}
```

`id: format!("U{}", layer)` となっているため、同じ layer には1つの宇宙しか作れません。これは設計上の問題かもしれません。

答えとしては、layer の数値だけでは宇宙を一意に特定できず、同じ層に複数の異なる実装や仕様が共存する可能性があります。

