// spec-core/src/udaf/refs.rs

use super::ids::{UniverseId, DomainId, SpecId};
use std::collections::HashSet;
use serde::{Deserialize, Serialize};

/// Type-safe set of specification references
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SpecSet {
    ids: HashSet<String>, // Internal storage as String for serialization
}

impl SpecSet {
    pub fn new() -> Self {
        Self { ids: HashSet::new() }
    }

    pub fn insert(&mut self, id: SpecId) -> bool {
        self.ids.insert(id.as_str().to_string())
    }

    pub fn contains(&self, id: &SpecId) -> bool {
        self.ids.contains(id.as_str())
    }

    pub fn remove(&mut self, id: &SpecId) -> bool {
        self.ids.remove(id.as_str())
    }

    pub fn len(&self) -> usize {
        self.ids.len()
    }

    pub fn is_empty(&self) -> bool {
        self.ids.is_empty()
    }

    pub fn iter(&self) -> impl Iterator<Item = SpecId> + '_ {
        self.ids.iter().filter_map(|s| SpecId::parse(s).ok())
    }

    /// Validate all references exist in the given set
    pub fn validate(&self, valid_ids: &HashSet<SpecId>) -> Result<(), Vec<String>> {
        let invalid: Vec<_> = self.ids.iter()
            .filter(|id| {
                SpecId::parse(id)
                    .ok()
                    .map(|spec_id| !valid_ids.contains(&spec_id))
                    .unwrap_or(true)
            })
            .cloned()
            .collect();

        if invalid.is_empty() {
            Ok(())
        } else {
            Err(invalid)
        }
    }
}

