```rust
// spec-core/src/udaf/ids.rs

use serde::{Deserialize, Serialize};
use std::fmt;
use std::str::FromStr;

/// Universe ID with compile-time layer validation
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct UniverseId(String);

impl UniverseId {
    /// Create root universe U0
    pub const fn root() -> Self {
        UniverseId(String::from("U0"))
    }

    /// Create projection universe from layer (U1, U2, U3, ...)
    pub fn projection(layer: u8) -> Result<Self, IdError> {
        if layer == 0 {
            return Err(IdError::InvalidLayer("U0 is reserved for root universe".into()));
        }
        Ok(UniverseId(format!("U{}", layer)))
    }

    /// Parse from string (for deserialization/user input)
    pub fn parse(s: &str) -> Result<Self, IdError> {
        if !s.starts_with('U') {
            return Err(IdError::InvalidFormat("Universe ID must start with 'U'".into()));
        }
        let layer_str = &s[1..];
        if layer_str.is_empty() {
            return Err(IdError::InvalidFormat("Missing layer number".into()));
        }
        // Validate it's a number
        layer_str.parse::<u8>()
            .map_err(|_| IdError::InvalidFormat("Layer must be a number".into()))?;
        Ok(UniverseId(s.to_string()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    pub fn layer(&self) -> u8 {
        self.0[1..].parse().unwrap_or(0)
    }
}

impl fmt::Display for UniverseId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl FromStr for UniverseId {
    type Err = IdError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        UniverseId::parse(s)
    }
}

