/// UDAF Model with type-safe IDs
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UDAFModel {
    pub universes: HashMap<UniverseId, Universe>,
    pub domains: HashMap<DomainId, Domain>,
    pub admissible_sets: HashMap<SpecId, AdmissibleSet>,
    pub transforms: HashMap<TransformId, TransformFunction>,
    pub metadata: Metadata,
}

impl UDAFModel {
    pub fn new() -> Self {
        let mut model = Self {
            universes: HashMap::new(),
            domains: HashMap::new(),
            admissible_sets: HashMap::new(),
            transforms: HashMap::new(),
            metadata: Metadata::new(),
        };

        model.universes.insert(UniverseId::root(), Universe::root());
        model
    }

    /// Validate all references in the model
    pub fn validate(&self) -> Result<(), Vec<String>> {
        let mut errors = Vec::new();

        // Collect all valid IDs
        let valid_spec_ids: HashSet<_> = self.admissible_sets.keys().cloned().collect();
        let valid_domain_ids: HashSet<_> = self.domains.keys().cloned().collect();
        let valid_universe_ids: HashSet<_> = self.universes.keys().cloned().collect();

        // Validate Universe references
        for universe in self.universes.values() {
            if let Err(invalid) = universe.specifications.validate(&valid_spec_ids) {
                errors.push(format!("Universe {} references invalid specs: {:?}", 
                    universe.id, invalid));
            }
        }

        // Validate Domain references
        for domain in self.domains.values() {
            if !valid_universe_ids.contains(&domain.universe_id) {
                errors.push(format!("Domain {} references invalid universe: {}", 
                    domain.id.as_str(), domain.universe_id));
            }
            if let Err(invalid) = domain.covered_by.validate(&valid_spec_ids) {
                errors.push(format!("Domain {} references invalid specs: {:?}", 
                    domain.id.as_str(), invalid));
            }
        }

        // Validate AdmissibleSet references
        for admissible in self.admissible_sets.values() {
            if !valid_universe_ids.contains(&admissible.universe_id) {
                errors.push(format!("AdmissibleSet {} references invalid universe: {}", 
                    admissible.spec_id.as_str(), admissible.universe_id));
            }
            if let Err(invalid) = admissible.contradicts.validate(&valid_spec_ids) {
                errors.push(format!("AdmissibleSet {} references invalid contradicting specs: {:?}", 
                    admissible.spec_id.as_str(), invalid));
            }
        }

        // Validate Transform references
        for transform in self.transforms.values() {
            if !valid_universe_ids.contains(&transform.source_universe) {
                errors.push(format!("Transform {} references invalid source universe: {}", 
                    transform.id.as_str(), transform.source_universe));
            }
            if !valid_universe_ids.contains(&transform.target_universe) {
                errors.push(format!("Transform {} references invalid target universe: {}", 
                    transform.id.as_str(), transform.target_universe));
            }
        }

        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }
}
